import type { Lang } from './lang';

// 多言語化 (2026-09-02 追加) の静的UI文言辞書。メニュー・カテゴリー・オプション名の翻訳は
// ここではなく pos.menu_* の translations 列 (設定画面「翻訳」タブ) で管理する — ここに置くのは
// ボタン・見出し・メッセージなど、コードに埋め込まれた固定文言のみ。
// キーは機能単位 (qr.*, cart.*, totals.* 等) でグループ化したフラットな dot-notation。
// {変数名} は t() 呼び出し時に differencesで置換される (例: t('table.label', { table: 'T3' }))。
// 日本語 (ja) が基準言語。他言語で未定義のキーは呼び出し側 (useLanguage) が ja にフォールバックする。

